void show_help ( Widget toplevel , const char * topic ) { size_t i ; static Widget help_shell = 0 ; static struct topic_info info ; static struct topic_item items [ NUM_HELP_TOPICS ] ; static Boolean first_time = True ; if ( help_shell == 0 ) { info . ok_callback = NULL ; info . items = items ; help_shell = create_topic_window ( toplevel , "xdvik: Help" , "help_window" , & info , initialize_items , "Close" , NULL ) ; info . shell = help_shell ; center_window ( help_shell , globals . widgets . top_level ) ; } { Dimension w , h ; XtVaGetValues ( help_shell , XtNwidth , & w , XtNheight , & h , NULL ) ; if ( h < 200 || w < 400 ) { XDVI_WARNING ( ( stderr , "Initial help window size too small (%dx%d); overriding size.\n" "Please check/update your application defaults file, and set both of\n" "`XDvi*help_text.rows' and `XDvi*help_text.columns' to a realistic value." , h , w ) ) ; XtVaSetValues ( help_shell , XtNwidth , 620 , XtNheight , 520 , NULL ) ; } } XtPopup ( help_shell , XtGrabNone ) ; if ( topic != NULL ) { Boolean matched = False ; for ( i = 0 ; info . items [ i ] . topic != NULL ; i ++ ) { if ( strcmp ( info . items [ i ] . topic , topic ) == 0 ) { select_topic ( & info , i ) ; matched = True ; } } if ( ! matched ) { XdviBell ( DISP , XtWindow ( help_shell ) , 0 ) ; popup_message ( help_shell , MSG_WARN , NULL , "Shouldn't happen: Could not find topic `%s' in help list!\n" REPORT_XDVI_BUG_TEMPLATE , topic ) ; } } if ( first_time ) { first_time = False ; select_topic ( & info , 0 ) ; } } 